import 'package:supabase_flutter/supabase_flutter.dart';
class AuthService { GoTrueClient get _auth => Supabase.instance.client.auth; Stream<AuthState> get onAuthStateChange => _auth.onAuthStateChange; Session? get currentSession => _auth.currentSession; Future<AuthResponse> signIn(String e,String p)=>_auth.signInWithPassword(email:e.trim(),password:p); Future<AuthResponse> signUp(String e,String p,{String? name})=>_auth.signUp(email:e.trim(),password:p,data:{'full_name':name?.trim()}); Future<void> resetPassword(String e)=>_auth.resetPasswordForEmail(e.trim()); Future<UserResponse> updatePassword(String p)=>_auth.updateUser(UserAttributes(password:p)); Future<void> signOut()=>_auth.signOut(); }
